void uart_port_isr(uint32_t periph)
{
    uart_port_t *p = port_of(periph);
    uint32_t guard = 0U;

    if (NULL == p) {
        (void)usart_data_receive(periph);
        return;
    }

    while ((RESET != usart_flag_get(periph, USART_FLAG_RBNE)) && (guard++ < 64U)) {
        uint8_t b = (uint8_t)usart_data_receive(periph);

        p->rx_bytes++;
        p->last_rx_ms = systick_get_ms();

        if (0U != p->echo) {
            /* Our own reply may be on the wire: either it is still being sent
               (tx_busy), or it has just finished and the receiver is still
               seeing the tail of the last byte through the direction buffer.
               Both are bounded in *time*: a fixed byte count is not, because
               whether the reply comes back at all depends on the transceiver -
               see UART_ECHO_WINDOW_BYTES. */
            if ((0U != p->tx_busy)
                || ((int32_t)(p->echo_until_us - us_now()) > 0)) {
                p->echoed++;
                continue;
            }
        }

        if (NULL != p->on_byte) {
            p->on_byte(p->index, b);
        } else {
            p->rx_dropped++;
        }
    }

    if (RESET != usart_flag_get(periph, USART_FLAG_ORERR)) {
        usart_flag_clear(periph, USART_FLAG_ORERR);
        (void)usart_data_receive(periph);
        p->rx_errors++;
    }

/* 1 Mbps on both buses, matching microduck's BAUD_RATE. */
#define BUS_BAUD_DEFAULT        1000000U
#define BUS_MIRROR_BAUD_DEFAULT 1000000U
#define DBG_BAUD_DEFAULT        115200U

/* Dynamixel baud-rate register code for 1 Mbps (XL330 table: 0=9600 ...
   3=1 Mbps). */

   protocols is not ignored for a second.  Measured need: the bench smoke test
   switches protocols back to back. */
#define BUS_PROTO_STICKY_MS 100U

/* One reply slot lives in board.h (BUS_SLOT_US): the slot rule is part of the
   wire contract, and src/bus_arb.c - which is deliberately free of any bus or
   hardware dependency - needs it too.

   A frame whose bytes are further apart than this is not one frame: drop the
   partial frame and re-sync on the next FF FF.  Well above the ~300 us slot of
   a live burst, far below the ~20 ms between host transactions. */
#define BUS_GAP_US          500U
/* The echo guard is not a byte count and does not live here: it is a *time*
   window after our own transmission completes (`UART_ECHO_WINDOW_BYTES` in
   src/uart_port.h), because whether our reply comes back at all depends on the
   transceiver.  A fixed byte count sat here once and silently ate the next
   request's `FF FF` on the real PCBA - see docs/bus_timing_borrow_plan.md §4.6.1. */

typedef struct {
    uint32_t rx_bytes;
    uint32_t tx_bytes;
    uint32_t rx_dropped;
    uint32_t rx_errors;
    uint32_t echoed;
    uint32_t frames;
    uint32_t answered;
    uint32_t responses;
    uint32_t bad_crc;
    uint32_t bad_len;
    uint32_t ignored;
    uint32_t deferred;      /* sync_read replies held for their slot  */
    uint32_t tx_lost;       /* replies dropped because TX was still busy */
    uint32_t gaps;          /* partial frames dropped by the gap rule */
    uint8_t  last_proto;
    uint8_t  enabled;
} bus_stats_t;

